'use strict';
const C=RepCore, KEY='rep-studio-v1', $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>crypto.randomUUID();
const days=['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
const icons={home:'<path d="m3 10 7-6 7 6v9H3z"/><path d="M8 19v-7h4v7"/>',routine:'<rect x="3" y="4" width="14" height="15" rx="2"/><path d="M7 2v4m6-4v4M6 10h8M6 14h5"/>',chart:'<path d="M3 3v15h15M6 13l4-5 4 2 4-6"/>',history:'<path d="M3 7a8 8 0 1 1-1 7M3 3v5h5M10 6v5l3 2"/>',settings:'<path d="M4 5h12M4 11h12M4 17h12"/><circle cx="8" cy="5" r="2"/><circle cx="13" cy="11" r="2"/><circle cx="7" cy="17" r="2"/>',plus:'<path d="M10 3v14M3 10h14"/>',arrow:'<path d="M3 10h14m-5-5 5 5-5 5"/>',lock:'<rect x="4" y="9" width="12" height="10" rx="2"/><path d="M6 9V6a4 4 0 0 1 8 0v3"/>',trophy:'<path d="M6 3h8v7a4 4 0 0 1-8 0zM6 5H3v3a3 3 0 0 0 3 3m8-6h3v3a3 3 0 0 1-3 3m-4 3v4m-4 0h8"/>',edit:'<path d="m3 14 10-10 3 3L6 17l-4 1zM11 6l3 3"/>',close:'<path d="m5 5 10 10M5 15 15 5"/>',download:'<path d="M10 2v11m-4-4 4 4 4-4M3 14v4h14v-4"/>',bolt:'<path d="m11 2-7 10h6l-1 7 7-11h-6z"/>'};
const icon=n=>`<span class="ico" aria-hidden="true"><svg viewBox="0 0 20 22">${icons[n]||icons.routine}</svg></span>`;
const btn=(text,action,cls='',ico='')=>`<button type="button" class="btn ${cls}" data-action="${action}">${ico?icon(ico):''}${text}</button>`;
let data=C.fresh(),view='home',selectedExercise='',saveError='',toastTimer;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);data=C.validate(parsed);if(parsed.draft&&typeof parsed.draft==='object'&&Array.isArray(parsed.draft.exercises)){try{const d=parsed.draft;const test={version:1,unit:data.unit,routines:[],workouts:[{...d,exercises:d.exercises.filter(e=>e.sets.length).map(e=>({...e,sets:e.sets.map(s=>({weightKg:s.weightKg??0,reps:s.reps??1}))}))}]};if(test.workouts[0].exercises.length)C.validate(test);if(typeof d.title==='string'&&typeof d.id==='string'&&typeof d.date==='string'&&d.exercises.length<=50)data.draft=d;}catch{saveError='No pudimos recuperar la sesión en curso. Tu historial sigue guardado.';}}}}catch{saveError='No se pudieron leer tus datos locales. Exporta una copia de recuperación en Ajustes antes de guardar datos nuevos.';}
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('es',{day:'numeric',month:'short'});
const fmt=(n,d=1)=>new Intl.NumberFormat('es',{maximumFractionDigits:d}).format(n);
const weight=kg=>fmt(C.fromKg(kg,data.unit));
function save(next=data){try{localStorage.setItem(KEY,JSON.stringify(next));data=next;saveError='';return true;}catch{saveError='No se pudo guardar. El almacenamiento está lleno o bloqueado. Exporta una copia antes de salir.';toast(saveError);return false;}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function go(v){view=v;render();window.scrollTo({top:0,behavior:'instant'});}
function render(){const nav=[['home','Hoy','home'],['routines','Rutinas','routine'],['progress','Progreso','chart'],['history','Historial','history'],['settings','Ajustes','settings']];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="logo"><span class="logo-mark">${icon('chart')}</span>REP<span style="color:#91a481">.</span></div><div class="tagline">UNA REPETICIÓN MÁS CERCA.</div><nav class="nav" aria-label="Navegación principal">${nav.map(([v,label,i])=>`<button data-view="${v}" class="${view===v||(view==='session'&&v==='home')?'active':''}" ${view===v?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('')}</nav><div class="sidebar-bottom">Pequeños pasos.<br>Progreso de verdad.<div class="profile"><span class="avatar">A</span><div><strong>Alek</strong><br>Tu espacio personal</div></div></div></aside><main class="main"><div class="topbar"><span class="eyebrow">TU DIARIO DE ENTRENAMIENTO</span><div class="logo mobile-logo"><span class="logo-mark">${icon('chart')}</span>REP.</div><div class="row"><span class="date">${new Date().toLocaleDateString('es',{weekday:'long',day:'numeric',month:'long'})}</span><span class="pill"><span class="dot"></span> Solo en este dispositivo</span></div></div>${saveError?`<p class="notice" role="alert">${esc(saveError)}</p><br>`:''}${({home:home,routines:routines,session:session,progress:progress,history:history,settings:settings}[view]||home)()}<div class="footer-note">${icon('lock')}<span>Tus datos se guardan en este navegador, no en la nube. Exporta una copia en Ajustes para no perderlos al borrar datos o cambiar de dispositivo.</span></div></main></div>`;}
function heading(title,sub,action=''){return `<div class="heading"><div><h1>${title}</h1><p class="muted">${sub}</p></div>${action}</div>`;}
function stat(label,value,foot,i){return `<div class="stat"><div class="stat-top">${label}${icon(i)}</div><div class="big">${value}</div><div class="stat-foot">${foot}</div></div>`;}
function empty(title,sub,action='',i='routine'){return `<div class="empty"><div class="empty-icon">${icon(i)}</div><h3>${title}</h3><p>${sub}</p>${action}</div>`;}
function totalSets(){return data.workouts.reduce((a,w)=>a+w.exercises.reduce((a,e)=>a+e.sets.length,0),0);}
function allPRs(){let prev=[],prs=[];for(const w of [...data.workouts].sort((a,b)=>a.date.localeCompare(b.date))){prs.push(...C.personalRecords(prev,w.exercises));prev.push(w);}return prs;}
function home(){const now=new Date(), monday=new Date(now);monday.setDate(now.getDate()-(now.getDay()+6)%7);const week=Array.from({length:7},(_,i)=>{const d=new Date(monday);d.setDate(d.getDate()+i);const iso=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return `<div class="day ${iso===today()?'today':''} ${data.workouts.some(w=>w.date===iso)?'done':''}"><span>${['L','M','X','J','V','S','D'][i]}</span><strong>${d.getDate()}</strong></div>`;}).join('');const recent=data.workouts.at(-1);const next=data.routines.find(r=>r.day===now.getDay())||data.routines[0];return `${heading('Cada rep cuenta.','Tu único rival es tu versión de ayer.')}<section class="hero"><div><div class="eyebrow">${data.draft?'TU SESIÓN TE ESPERA':'A TU RITMO. A TU MANERA.'}</div><h2>${data.draft?'Lo que empiezas,<br>también cuenta.':data.workouts.length?'Sigue construyendo<br>tu mejor versión.':'Tu próxima victoria<br>empieza aquí.'}</h2><p>${data.draft?'Tienes un entrenamiento en curso. Puedes retomarlo justo donde lo dejaste.':'Registra tu entrenamiento. Mira lo que has avanzado. Celebra cada pequeña mejora.'}</p>${btn(data.draft?'Continuar entrenamiento':'Empezar entrenamiento','start','lime','arrow')}</div><div class="sculpture" aria-hidden="true"><span class="spark">✦</span><svg viewBox="0 0 140 140"><rect x="27" y="63" width="86" height="15" rx="5" fill="#d9eeaa"/><rect x="19" y="38" width="20" height="65" rx="7" fill="#b3d274"/><rect x="34" y="29" width="19" height="83" rx="7" fill="#d3ed90"/><rect x="87" y="29" width="19" height="83" rx="7" fill="#d3ed90"/><rect x="103" y="38" width="20" height="65" rx="7" fill="#b3d274"/><path d="M39 37v66m53-66v66" stroke="#efffd0" stroke-width="3" opacity=".6"/></svg></div></section><div class="stats">${stat('Entrenamientos',data.workouts.length,'Sesiones guardadas','bolt')}${stat('Series completadas',totalSets(),'Una a una, suman','routine')}${stat('Récords superados',allPRs().length,'Mismo ejercicio y reps','trophy')}</div><div class="grid"><section class="card"><div class="section-title"><h2>Tu semana, en movimiento</h2><span class="muted">${now.toLocaleDateString('es',{month:'short'})}</span></div><div class="week">${week}</div>${next?`<div class="quote"><div class="row"><div><span class="eyebrow">${days[next.day]}</span><h3 style="margin-top:7px">${esc(next.name)}</h3><span>${next.exercises.length} ejercicios · ${next.exercises.reduce((a,e)=>a+e.targetSets,0)} series previstas</span></div><button class="icon-btn" data-start="${next.id}" aria-label="Empezar ${esc(next.name)}">${icon('arrow')}</button></div></div>`:empty('Dale un lugar a tu rutina','Organiza tus ejercicios por día. Sin planes complicados, solo lo que funciona para ti.',btn('Crear mi primera rutina','new-routine','secondary','plus'))}</section><section class="card"><div class="section-title"><h2>La vista de tu progreso</h2><button class="text-btn" data-view="progress">Ver todo →</button></div>${recent?`<p class="muted">Última sesión · ${dateLabel(recent.date)}</p><h3 style="margin:15px 0">${esc(recent.title)}</h3><div class="big">${recent.exercises.reduce((a,e)=>a+e.sets.length,0)} <small>series completadas</small></div><p class="muted">${recent.exercises.map(e=>esc(e.name)).join(' · ')}</p>`:`<p class="muted">Aquí verás crecer tus marcas.</p><div class="chart-empty">Tu primera sesión es el punto de partida.</div>`}<div class="quote"><strong>No todos los días toca un récord.</strong><br>Presentarte y registrar tu esfuerzo también es avanzar.</div></section></div>`;}
function routines(){return `${heading('Tus rutinas.','Menos pensar. Más entrenar.',btn('Nueva rutina','new-routine','','plus'))}${data.routines.length?`<div class="routine-grid">${data.routines.map(r=>`<article class="card routine"><div class="row"><span class="badge">${days[r.day].toUpperCase()}</span><button class="icon-btn" data-edit="${r.id}" aria-label="Editar ${esc(r.name)}">${icon('edit')}</button></div><h2>${esc(r.name)}</h2><p class="muted">${r.exercises.length} ejercicios · ${r.exercises.reduce((a,e)=>a+e.targetSets,0)} series previstas</p><ul>${r.exercises.map(e=>`<li>${esc(e.name)} <span style="float:right">${e.targetSets} series</span></li>`).join('')}</ul><div class="actions"><button class="btn secondary" data-start="${r.id}">Empezar rutina ${icon('arrow')}</button></div></article>`).join('')}</div>`:`<div class="card">${empty('Tu rutina, tus reglas.','Elige un día, ponle nombre y añade tus ejercicios. Podrás cambiarlo cuando quieras.',btn('Crear mi primera rutina','new-routine','','plus'))}</div>`}`;}
const round=n=>Math.round(n*1000)/1000;
function session(){if(!data.draft)return home();const d=data.draft,all=d.exercises.flatMap(e=>e.sets),done=all.filter(s=>s.done).length;return `${heading(esc(d.title),'Marca las series que completes. El borrador se guarda aquí.')}<div class="session-head"><div class="row"><span class="muted">${dateLabel(d.date)} · ${data.unit.toUpperCase()}</span><strong style="font-size:12px">${done} / ${all.length} series</strong></div><div class="bar" style="margin-top:12px"><span style="width:${all.length?done/all.length*100:0}%"></span></div></div>${d.exercises.map((e,ei)=>`<section class="card exercise-card"><div class="row"><div><h3>${esc(e.name)}</h3><p class="hint">${e.mode==='assisted'?'Peso de asistencia. No genera récord de carga.':'Carga registrada · usa siempre la misma convención.'}</p></div><button class="icon-btn" data-remove-exercise="${ei}" aria-label="Quitar ${esc(e.name)}">${icon('close')}</button></div><div class="set-grid header"><span>Serie</span><span style="text-align:center">${data.unit}</span><span style="text-align:center">Reps</span><span style="text-align:center">Lista</span><span></span></div>${e.sets.map((s,si)=>`<div class="set-grid ${s.done?'checked-row':''}"><span class="number">${si+1}</span><input type="number" inputmode="decimal" min="0" max="${data.unit==='kg'?1500:3306}" step="any" value="${s.weightKg===null?'':round(C.fromKg(s.weightKg,data.unit))}" placeholder="0" aria-label="${esc(e.name)}, serie ${si+1}, ${data.unit}" data-e="${ei}" data-s="${si}" data-field="weight"><input type="number" inputmode="numeric" min="1" max="999" step="1" value="${s.reps===null?'':s.reps}" placeholder="8" aria-label="${esc(e.name)}, serie ${si+1}, repeticiones" data-e="${ei}" data-s="${si}" data-field="reps"><button class="check ${s.done?'checked':''}" data-check="${ei},${si}" aria-label="${s.done?'Desmarcar':'Completar'} serie ${si+1} de ${esc(e.name)}" aria-pressed="${!!s.done}">✓</button><button class="remove" data-remove-set="${ei},${si}" aria-label="Quitar serie ${si+1}">×</button></div>`).join('')}<button class="text-btn" data-add-set="${ei}" style="width:100%;margin-top:12px">+ Añadir serie</button></section>`).join('')}${!d.exercises.length?`<div class="card">${empty('Empecemos por un ejercicio.','Añade un ejercicio y registra el peso y las repeticiones de cada serie.')}</div>`:''}<div class="row">${btn('Añadir ejercicio','add-exercise','secondary','plus')}${btn('Descartar','discard','ghost')}</div><div class="session-bottom"><div class="muted"><strong>${done} series</strong><br>Listas para guardar</div>${btn('Terminar sesión','finish','','arrow')}</div>`;}
function progress(){const ex=new Map();data.workouts.forEach(w=>w.exercises.forEach(e=>ex.set(e.key,{name:e.name,mode:e.mode})));if(!ex.size)return `${heading('Mira lo lejos que llegas.','Tu progreso, sin compararte con nadie más.')}<div class="card">${empty('Todo empieza con una serie.','Registra un entrenamiento para ver tus marcas, tu evolución y tus récords.',btn('Registrar entrenamiento','start','','arrow'),'chart')}</div>`;if(!ex.has(selectedExercise))selectedExercise=ex.keys().next().value;const chosen=ex.get(selectedExercise),sessions=[...data.workouts].sort((a,b)=>a.date.localeCompare(b.date)).map(w=>({...w,sets:w.exercises.filter(e=>e.key===selectedExercise).flatMap(e=>e.sets)})).filter(w=>w.sets.length);const kg=sessions.map(w=>Math.max(...w.sets.map(s=>s.weightKg))),max=Math.max(...kg),min=Math.min(...kg),first=kg[0],last=kg.at(-1),delta=last-first;const reps=[...new Set(sessions.flatMap(w=>w.sets.map(s=>s.reps)))].sort((a,b)=>a-b);const graph=sessions.slice(-12),vals=graph.map(w=>C.fromKg(Math.max(...w.sets.map(s=>s.weightKg)),data.unit)),low=Math.min(...vals)*.85,high=Math.max(...vals)*1.1||1,span=high-low||1;const pts=vals.map((v,i)=>[40+(vals.length===1?190:i/(vals.length-1)*380),155-(v-low)/span*125]);return `${heading('Mira lo lejos que llegas.','El progreso real tiene su propio ritmo.')}<div class="section-title"><label for="exercise-filter" style="margin:0">Ejercicio</label><select id="exercise-filter" class="slim">${[...ex].map(([k,e])=>`<option value="${esc(k)}" ${k===selectedExercise?'selected':''}>${esc(e.name)}${e.mode==='assisted'?' (asistido)':''}</option>`).join('')}</select></div><div class="stats">${stat(chosen.mode==='assisted'?'Mayor asistencia':'Mayor carga',`${weight(max)} <small>${data.unit}</small>`,'Entre todas las series','trophy')}${stat('Sesiones',sessions.length,'Con este ejercicio','routine')}${stat('Primera → última',`${delta>0?'+':''}${weight(delta)} <small>${data.unit}</small>`,'Diferencia de carga máxima','chart')}</div><div class="card"><div class="section-title"><h2>${chosen.mode==='assisted'?'Asistencia registrada':'Tu evolución de carga'}</h2><span class="muted">${data.unit}</span></div><p class="muted">Máxima ${chosen.mode==='assisted'?'asistencia':'carga'} por sesión · últimas ${graph.length} sesiones.</p><svg class="chart" viewBox="0 0 460 200" role="img" aria-label="Gráfico de carga máxima por sesión. Los datos exactos están en la lista inferior.">${[0,1,2].map(i=>`<line x1="40" y1="${30+i*62}" x2="420" y2="${30+i*62}" stroke="#e8ece3"/><text x="0" y="${34+i*62}">${fmt(high-i*span/2,0)}</text>`).join('')}${pts.length>1?`<path d="M${pts.map(p=>p.join(',')).join(' L')}" fill="none" stroke="#446a46" stroke-width="3" stroke-linejoin="round"/>`:''}${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="#a9c773" stroke="#fff" stroke-width="2"><title>${dateLabel(graph[i].date)}: ${fmt(vals[i])} ${data.unit}</title></circle>`).join('')}<text x="40" y="185">${dateLabel(graph[0].date)}</text><text x="420" y="185" text-anchor="end">${dateLabel(graph.at(-1).date)}</text></svg><p class="hint">${chosen.mode==='assisted'?'En ejercicios asistidos, más peso significa más ayuda. No celebramos aumentos como récords.':'La carga máxima no mide por sí sola tu fuerza. Para comparar marcas, usa el mismo ejercicio, equipo y número de repeticiones.'}</p><details style="margin-top:15px"><summary class="muted">Ver datos del gráfico</summary>${graph.map((w,i)=>`<div class="record-row"><span>${dateLabel(w.date)} · ${esc(w.title)}</span><strong>${fmt(vals[i])} ${data.unit}</strong></div>`).join('')}</details></div><div class="card" style="margin-top:18px"><div class="section-title"><h2>${chosen.mode==='assisted'?'Tus registros por repeticiones':'Tus mejores marcas'}</h2>${icon('trophy')}</div><p class="muted">${chosen.mode==='assisted'?'Menor asistencia registrada para cada número de repeticiones.':'Mayor carga para el mismo número de repeticiones.'}</p>${reps.map(r=>{const values=sessions.flatMap(w=>w.sets).filter(s=>s.reps===r).map(s=>s.weightKg);const best=chosen.mode==='assisted'?Math.min(...values):Math.max(...values);return `<div class="record-row"><strong>${r} repeticiones</strong><span>${weight(best)} ${data.unit} <span class="badge-record">${values.length===1?'Punto de partida':'Mejor marca'}</span></span></div>`;}).join('')}</div>`;}
function history(){return `${heading('Todo lo que has sumado.','Tu esfuerzo, guardado sesión a sesión.')}<section class="card">${data.workouts.length?[...data.workouts].reverse().map(w=>`<details class="history-item"><summary><div class="row"><div><p class="eyebrow" style="color:var(--muted);margin-bottom:7px">${dateLabel(w.date)}</p><h3>${esc(w.title)}</h3><p class="muted">${w.exercises.length} ejercicios · ${w.exercises.reduce((a,e)=>a+e.sets.length,0)} series</p></div><span aria-hidden="true">⌄</span></div></summary><div class="sets-list">${w.exercises.map(e=>`<strong>${esc(e.name)}</strong>${e.mode==='assisted'?' · asistencia':''}<br>${e.sets.map(s=>`${weight(s.weightKg)} ${data.unit} × ${s.reps}`).join(' &nbsp;·&nbsp; ')}<br><br>`).join('')}</div><button class="btn danger" data-delete-workout="${w.id}">Eliminar sesión</button></details>`).join(''):empty('Aquí empieza tu historia.','Cuando termines un entrenamiento, aparecerá aquí. Sin datos de ejemplo ni marcas inventadas.',btn('Empezar entrenamiento','start','','arrow'),'history')}</section>`;}
function settings(){return `${heading('A tu manera.','Lo esencial, bajo tu control.')}<div class="settings"><section class="card"><div class="row"><div><h2>Unidad de peso</h2><p class="muted" style="margin-top:8px">Se convierten también tus registros anteriores.</p></div><select id="unit" aria-label="Unidad de peso"><option ${data.unit==='kg'?'selected':''}>kg</option><option ${data.unit==='lb'?'selected':''}>lb</option></select></div><p class="hint">Registra siempre de la misma forma: peso total de la barra, por mancuerna o de la máquina. Incluye el equipo en el nombre para no mezclar marcas.</p></section><section class="card"><h2>Tus datos son tuyos.</h2><p class="muted" style="margin-top:10px">Este registro vive solo en este navegador y dispositivo. No hay cuenta de entrenamiento ni sincronización en la nube. El modo privado y borrar los datos del navegador pueden eliminarlo.</p><div class="row" style="justify-content:flex-start;flex-wrap:wrap">${btn('Exportar copia','export','secondary','download')}${btn('Importar copia','import','secondary')}</div><input type="file" accept="application/json,.json" id="import-file" hidden><p class="hint">La copia JSON contiene rutinas e historial. Guárdala en un lugar privado. Importar reemplaza los datos actuales y descarta el entrenamiento en curso.</p>${saveError?btn('Exportar recuperación','recover','secondary'):''}</section><section class="card"><h2>Hecho para volver.</h2><p class="muted" style="margin-top:10px">Una animación breve celebra cuando superas una carga anterior con el mismo ejercicio y las mismas repeticiones. Tu primera marca es tu punto de partida, no un récord superado.</p><p class="hint">Respetamos la preferencia de reducir movimiento del dispositivo. Los ejercicios asistidos no generan récords de carga. REP es un diario, no un plan de entrenamiento ni asesoramiento de salud.</p><div class="source-links">Referencias de experiencia y registro:<br><a href="https://www.hevyapp.com/features/gym-performance/" target="_blank" rel="noopener noreferrer">Hevy: progreso →</a><a href="https://help.strongapp.io/article/229-my-first-workout" target="_blank" rel="noopener noreferrer">Strong: registro →</a><br>Diseño original de REP · sin conexión con estas marcas.</div></section></div>`;}
function openModal(html){$('#modal').innerHTML=html;$('#modal').showModal();}function closeModal(){$('#modal').close();}
function modalTop(title,sub=''){return `<div class="modal-top"><div><h2>${title}</h2>${sub?`<p class="muted">${sub}</p>`:''}</div><button class="icon-btn" data-action="close" aria-label="Cerrar">${icon('close')}</button></div>`;}
function ask(title,sub,onYes,label='Confirmar'){openModal(`${modalTop(title)}<p class="muted" style="margin-top:15px">${sub}</p><div class="form-actions">${btn('Cancelar','close','secondary')}<button class="btn" id="confirm">${label}</button></div>`);$('#confirm').onclick=()=>{closeModal();onYes();};}
let editing=null,editExercises=[];
function editRoutine(id){editing=id||null;const r=data.routines.find(r=>r.id===id);editExercises=r?structuredClone(r.exercises):[{name:'',mode:'weight',targetSets:3}];openModal(`${modalTop(r?'Editar rutina':'Tu nueva rutina','Un día, unos ejercicios y ganas de volver.')}<form id="routine-form"><div class="form-row"><div><label for="routine-name">Nombre</label><input id="routine-name" maxlength="120" required placeholder="Ej. Tren superior" value="${esc(r?.name||'')}"></div><div><label for="routine-day">Día</label><select id="routine-day">${days.map((d,i)=>`<option value="${i}" ${i===(r?.day??new Date().getDay())?'selected':''}>${d}</option>`).join('')}</select></div></div><label>Ejercicios</label><p class="hint">Distingue el equipo: “Press banca · barra” y “Press banca · mancuernas”.</p><div id="routine-exercises"></div>${btn('Añadir ejercicio','routine-add','ghost','plus')}<p class="error" id="form-error" role="alert"></p><div class="form-actions">${r?btn('Eliminar','delete-routine','danger'):btn('Cancelar','close','secondary')}<button class="btn" type="submit">Guardar rutina</button></div></form>`);renderRoutineExercises();$('#routine-form').onsubmit=ev=>{ev.preventDefault();syncRoutine();const name=$('#routine-name').value.trim(),day=Number($('#routine-day').value);if(!name||editExercises.some(e=>!e.name.trim()||!Number.isInteger(e.targetSets)||e.targetSets<1||e.targetSets>20))return $('#form-error').textContent='Añade un nombre y entre 1 y 20 series por ejercicio.';const exercises=editExercises.map(e=>({...e,name:e.name.trim(),key:C.key(e.name,e.mode)}));if(new Set(exercises.map(e=>e.key)).size!==exercises.length)return $('#form-error').textContent='Ese ejercicio ya está en la rutina. Cambia el nombre si es otra variante.';const next=structuredClone(data),routine={id:editing||uid(),name,day,exercises};if(editing)next.routines[next.routines.findIndex(r=>r.id===editing)]=routine;else next.routines.push(routine);if(save(next)){closeModal();go('routines');toast('Rutina guardada. Un paso menos antes de entrenar.');}};}
function renderRoutineExercises(){$('#routine-exercises').innerHTML=editExercises.map((e,i)=>`<div class="exercise-edit"><div class="row"><strong class="muted">Ejercicio ${i+1}</strong><button type="button" class="icon-btn" data-routine-remove="${i}" aria-label="Quitar ejercicio ${i+1}" ${editExercises.length===1?'disabled':''}>${icon('close')}</button></div><input required maxlength="120" placeholder="Ej. Sentadilla · barra" aria-label="Nombre del ejercicio ${i+1}" data-rname="${i}" value="${esc(e.name)}"><div class="form-row"><div><label for="mode-${i}">Tipo de carga</label><select id="mode-${i}" data-rmode="${i}"><option value="weight" ${e.mode==='weight'?'selected':''}>Peso levantado</option><option value="assisted" ${e.mode==='assisted'?'selected':''}>Peso de asistencia</option></select></div><div><label for="sets-${i}">Series</label><input id="sets-${i}" type="number" min="1" max="20" required data-rsets="${i}" value="${e.targetSets}"></div></div></div>`).join('');}
function syncRoutine(){editExercises=editExercises.map((e,i)=>({name:$(`[data-rname="${i}"]`).value,mode:$(`[data-rmode="${i}"]`).value,targetSets:Number($(`[data-rsets="${i}"]`).value)}));}
function start(id){if(data.draft){if(id)toast('Primero termina o descarta la sesión en curso.');go('session');return;}if(!id&&data.routines.length){openModal(`${modalTop('¿Qué toca hoy?','Elige una rutina o entrena por libre.')}<div class="stack" style="margin-top:22px">${data.routines.map(r=>`<button class="btn secondary" data-start="${r.id}" style="justify-content:space-between">${esc(r.name)}<span class="hint" style="margin:0">${days[r.day]}</span></button>`).join('')}${btn('Entrenamiento libre','free','','plus')}</div>`);return;}startDraft(data.routines.find(r=>r.id===id));}
function startDraft(r){const next=structuredClone(data);next.draft={id:uid(),title:r?.name||'Entrenamiento libre',date:today(),exercises:r?r.exercises.map(e=>({key:e.key,name:e.name,mode:e.mode,sets:Array.from({length:e.targetSets},()=>({weightKg:null,reps:null,done:false}))})):[]};if(save(next)){closeModal();go('session');if(!r)addExercise();}}
function addExercise(){const known=new Map();[...data.routines.flatMap(r=>r.exercises),...data.workouts.flatMap(w=>w.exercises)].forEach(e=>known.set(e.key,e));openModal(`${modalTop('Añadir ejercicio','Usa el mismo nombre para comparar tus marcas.')}<form id="exercise-form"><label for="exercise-name">Nombre y equipo</label><input id="exercise-name" required maxlength="120" list="known-exercises" placeholder="Ej. Press banca · barra"><datalist id="known-exercises">${[...known.values()].map(e=>`<option value="${esc(e.name)}"></option>`).join('')}</datalist><label for="exercise-mode">Tipo de carga</label><select id="exercise-mode"><option value="weight">Peso levantado</option><option value="assisted">Peso de asistencia</option></select><p class="hint">Si la máquina te ayuda a levantar tu cuerpo, elige asistencia. Sin carga externa, registra 0.</p><p id="exercise-error" class="error" role="alert"></p><div class="form-actions">${btn('Cancelar','close','secondary')}<button class="btn" type="submit">Añadir ejercicio</button></div></form>`);$('#exercise-form').onsubmit=ev=>{ev.preventDefault();const name=$('#exercise-name').value.trim(),mode=$('#exercise-mode').value,k=C.key(name,mode);if(!name)return;if(data.draft.exercises.some(e=>e.key===k))return $('#exercise-error').textContent='Ya está en tu sesión. Añade más series a ese ejercicio.';const next=structuredClone(data);next.draft.exercises.push({key:k,name,mode,sets:[{weightKg:null,reps:null,done:false}]});if(save(next)){closeModal();render();}};}
function finish(){const d=data.draft,exercises=d.exercises.map(e=>({...e,sets:e.sets.filter(s=>s.done).map(s=>({weightKg:s.weightKg,reps:s.reps}))})).filter(e=>e.sets.length);if(!exercises.length)return toast('Completa al menos una serie antes de guardar.');const incomplete=d.exercises.flatMap(e=>e.sets).filter(s=>!s.done).length;const commit=()=>{const prs=C.personalRecords(data.workouts,exercises),next=structuredClone(data);next.workouts.push({id:d.id,title:d.title,date:d.date,exercises});next.draft=null;if(save(next)){go('home');if(prs.length)celebrate(prs);else openModal(`<div class="celebrate"><div class="medal">✓</div><div class="eyebrow">SESIÓN GUARDADA</div><h2 style="margin-top:12px">Hoy también has sumado.</h2><p class="muted" style="margin-top:12px">${data.workouts.length===1?'Tu primera sesión es tu punto de partida. Aquí empieza tu progreso.':'El hábito también es una victoria. Tu esfuerzo ya forma parte de tu historia.'}</p>${btn('Vamos a por la próxima','close')}</div>`);}};if(incomplete)ask('¿Guardar lo completado?',`${incomplete} series no están marcadas. Se guardarán solo las series completadas y se descartarán las demás.`,commit,'Guardar sesión');else commit();}
function celebrate(prs){const p=prs[0];openModal(`<div class="celebrate"><div class="medal">✦</div><div class="eyebrow">NUEVA MEJOR MARCA</div><h2 style="margin-top:12px">Un poco más lejos.</h2><p class="muted" style="margin-top:10px">${esc(p.name)} · ${p.reps} repeticiones</p><div class="big">${weight(p.kg)} <small>${data.unit}</small></div><span class="badge-record">+${weight(p.kg-p.previous)} ${data.unit} sobre tu marca anterior</span><p class="muted" style="margin-top:15px">Antes: ${weight(p.previous)} ${data.unit} × ${p.reps}${prs.length>1?`<br>Y ${prs.length-1} ${prs.length===2?'marca más superada':'marcas más superadas'} en esta sesión.`:''}</p>${btn('Me quedo con esta victoria','close')}</div>`);if(!matchMedia('(prefers-reduced-motion: reduce)').matches){$('#confetti').innerHTML=Array.from({length:28},(_,i)=>`<i style="left:${Math.random()*100}%;background:${['#d3ed90','#e3a65f','#719779'][i%3]};animation-delay:${Math.random()*.3}s;transform:rotate(${i*17}deg)"></i>`).join('');setTimeout(()=>$('#confetti').innerHTML='',2200);}}
function download(content,name){const blob=new Blob([content],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportData(){download(JSON.stringify({...data,draft:null},null,2),`rep-copia-${today()}.json`);toast('Copia preparada. Guárdala en un lugar privado.');}
async function importData(file){if(!file)return;if(file.size>5*1024*1024)return toast('El archivo es demasiado grande. Máximo: 5 MB.');let parsed;try{parsed=C.validate(JSON.parse(await file.text()));}catch(e){return toast(e.message?.startsWith('La copia')?e.message:'No se pudo leer el archivo JSON. No se ha cambiado nada.');}ask('¿Reemplazar tus datos?',`La copia contiene ${parsed.routines.length} rutinas y ${parsed.workouts.length} sesiones. Reemplazará tus ${data.routines.length} rutinas y ${data.workouts.length} sesiones actuales y descartará el entrenamiento en curso. Exporta antes si quieres conservarlos.`,()=>{if(save(parsed)){render();toast('Copia importada correctamente.');}},'Reemplazar datos');}
$('#app').addEventListener('input',ev=>{const t=ev.target;if(t.dataset.field){const s=data.draft.exercises[Number(t.dataset.e)].sets[Number(t.dataset.s)];const n=t.value===''?null:Number(t.value);if(t.dataset.field==='weight')s.weightKg=n===null?null:C.toKg(n,data.unit);else s.reps=n;s.done=false;save();const row=t.closest('.set-grid');row.classList.remove('checked-row');row.querySelector('.check').classList.remove('checked');row.querySelector('.check').setAttribute('aria-pressed','false');}});
document.addEventListener('change',ev=>{const t=ev.target;if(t.id==='unit'){const next=structuredClone(data);next.unit=t.value;if(save(next)){render();toast(`Pesos convertidos a ${data.unit}.`);}}if(t.id==='exercise-filter'){selectedExercise=t.value;render();}if(t.id==='import-file')importData(t.files[0]);});
document.addEventListener('click',ev=>{const t=ev.target.closest('button');if(!t)return;if(t.dataset.view)return go(t.dataset.view);if(t.dataset.start)return start(t.dataset.start);if(t.dataset.edit)return editRoutine(t.dataset.edit);if(t.dataset.routineRemove!==undefined){syncRoutine();editExercises.splice(Number(t.dataset.routineRemove),1);renderRoutineExercises();return;}if(t.dataset.deleteWorkout){const id=t.dataset.deleteWorkout;return ask('¿Eliminar esta sesión?','No se puede deshacer desde la app. Tus marcas se recalcularán. Puedes exportar una copia primero.',()=>{const next=structuredClone(data);next.workouts=next.workouts.filter(w=>w.id!==id);if(save(next)){render();toast('Sesión eliminada.');}},'Eliminar sesión');}if(t.dataset.check){const [ei,si]=t.dataset.check.split(',').map(Number),s=data.draft.exercises[ei].sets[si];if(s.weightKg===null||!Number.isFinite(s.weightKg)||s.weightKg<0||s.weightKg>1500||!Number.isInteger(s.reps)||s.reps<1||s.reps>999)return toast('Introduce un peso entre 0 y 1500 kg y entre 1 y 999 repeticiones.');s.done=!s.done;if(save())render();return;}if(t.dataset.addSet!==undefined){const e=data.draft.exercises[Number(t.dataset.addSet)];if(e.sets.length>=100)return toast('Máximo 100 series por ejercicio.');e.sets.push({weightKg:null,reps:null,done:false});if(save())render();return;}if(t.dataset.removeSet){const [ei,si]=t.dataset.removeSet.split(',').map(Number);const remove=()=>{data.draft.exercises[ei].sets.splice(si,1);if(save())render();};return data.draft.exercises[ei].sets[si].done?ask('¿Quitar esta serie?','Esta serie ya estaba completada.',remove,'Quitar serie'):remove();}if(t.dataset.removeExercise!==undefined){const ei=Number(t.dataset.removeExercise);return ask('¿Quitar el ejercicio?','Se quitarán también sus series de esta sesión. El historial anterior no cambia.',()=>{data.draft.exercises.splice(ei,1);if(save())render();},'Quitar ejercicio');}
const actions={'start':()=>start(),'free':()=>startDraft(),'close':closeModal,'new-routine':()=>editRoutine(),'routine-add':()=>{syncRoutine();if(editExercises.length>=50)return toast('Máximo 50 ejercicios.');editExercises.push({name:'',mode:'weight',targetSets:3});renderRoutineExercises();},'delete-routine':()=>{const id=editing;ask('¿Eliminar esta rutina?','Tus entrenamientos guardados no se eliminarán.',()=>{const next=structuredClone(data);next.routines=next.routines.filter(r=>r.id!==id);if(save(next)){go('routines');toast('Rutina eliminada.');}},'Eliminar rutina');},'add-exercise':()=>{if(data.draft.exercises.length>=50)return toast('Máximo 50 ejercicios.');addExercise();},'discard':()=>ask('¿Descartar esta sesión?','Se perderá el borrador de este entrenamiento. Tu historial no cambia.',()=>{const next=structuredClone(data);next.draft=null;if(save(next))go('home');},'Descartar sesión'),'finish':finish,'export':exportData,'import':()=>$('#import-file').click(),'recover':()=>{try{download(localStorage.getItem(KEY)||'{}',`rep-recuperacion-${today()}.json`);}catch{toast('El navegador no permite acceder al almacenamiento.');}}};if(actions[t.dataset.action])actions[t.dataset.action]();});
window.addEventListener('storage',ev=>{if(ev.key===KEY){toast('Los datos cambiaron en otra pestaña. Recarga antes de continuar.');}});
render();
